const bookings = $input.first().json.bookings || [];
const now = new Date();
const todayStr = now.toISOString().slice(0, 10);
const nowMins = now.getHours() * 60 + now.getMinutes();

const completedRecently = [];

for (const b of bookings) {
  if (b.status !== 'confirmed' || b.booking_date !== todayStr) continue;
  const [h, m] = b.end_time.split(':').map(Number);
  const endMins = h * 60 + m;
  const diff = nowMins - endMins;

  // Finished between 30 and 90 mins ago
  if (diff >= 30 && diff <= 90) {
    completedRecently.push({
      bookingRef: b.booking_ref,
      customerPhone: b.customer_phone,
      customerName: b.customer_name,
      courtName: b.court_name
    });
  }
}

return completedRecently.map(item => ({ json: item }));
